class Solution {
public:
    int findRadius(vector<int>& houses, vector<int>& heaters) {
        sort(heaters.begin(), heaters.end());
        int res = 0;
        for (int h : houses) {
            auto it = lower_bound(heaters.begin(), heaters.end(), h);
            int d = INT_MAX;
            if (it != heaters.end()) d = min(d, *it - h);
            if (it != heaters.begin()) d = min(d, h - *(it - 1));
            res = max(res, d);
        }
        return res;
    }
};

class Solution {
    public int findRadius(int[] houses, int[] heaters) {
        Arrays.sort(heaters);
        int res = 0;
        for (int h : houses) {
            int idx = Arrays.binarySearch(heaters, h);
            if (idx < 0) {
                idx = -(idx + 1);
            }
            int d1 = idx > 0 ? h - heaters[idx - 1] : Integer.MAX_VALUE;
            int d2 = idx < heaters.length ? heaters[idx] - h : Integer.MAX_VALUE;
            res = Math.max(res, Math.min(d1, d2));
        }
        return res;
    }
}

var findRadius = function(houses, heaters) {
    heaters.sort((a, b) => a - b);
    let res = 0;
    for (const h of houses) {
        let left = 0, right = heaters.length;
        while (left < right) {
            const mid = Math.floor((left + right) / 2);
            if (heaters[mid] < h) left = mid + 1;
            else right = mid;
        }
        const d1 = left > 0 ? h - heaters[left - 1] : Infinity;
        const d2 = left < heaters.length ? heaters[left] - h : Infinity;
        res = Math.max(res, Math.min(d1, d2));
    }
    return res;
};
